"""Audit trail: every SQL statement executed on behalf of a client (generated, retried or hand-edited).

Endpoints set the request context once; datasources.execute() records each statement it runs. Statements run
outside a request (schema introspection, evals, CLI) are not recorded.
"""
import contextvars
import sqlite3

from . import config, history

_ctx: contextvars.ContextVar[dict | None] = contextvars.ContextVar("audit_ctx", default=None)


def set_context(request_id: str, client: str, kind: str) -> None:
    """kind: 'ask' (generated by the model) or 'execute' (SQL submitted by the client)."""
    _ctx.set({"request_id": request_id, "client": client, "kind": kind})


def record(source_id: str, sql: str, status: str, row_count: int | None = None,
           error: str | None = None, duration_ms: float | None = None) -> None:
    ctx = _ctx.get()
    if ctx is None:
        return
    try:
        history.add_audit(request_id=ctx["request_id"], client=ctx["client"], kind=ctx["kind"],
                          source_id=source_id, sql=sql[:20000], status=status, row_count=row_count,
                          error=(error or None) and error[:2000], duration_ms=duration_ms)
    except sqlite3.Error:  # auditing must never break a query
        pass


def prune() -> None:
    if config.AUDIT_RETENTION_DAYS > 0:
        history.prune_audit(config.AUDIT_RETENTION_DAYS)
